beforeSaveCustomScript:
if (contactType == 'Volunteer' || contactType == 'Employee') {
    if (weeklyHours != null) {
        monthlyHours = number\round(weeklyHours * 4.33, 1);
    } else {
        monthlyHours = null;
    }
}
if ((contactType == 'Volunteer' || contactType == 'Employee') && entity\isNew() && startDate == null) {
    startDate = datetime\today();
}
if (contactType == 'MemberContact' && entity\isNew() && joinDate == null) {
    joinDate = datetime\today();
}
if ((contactType == 'Volunteer' || contactType == 'Employee') && endDate != null && endDate < datetime\today()) {
    personnelStatus = 'Inactive';
} else if ((contactType == 'Volunteer' || contactType == 'Employee') && startDate != null && startDate > datetime\today()) {
    personnelStatus = 'Inactive';
} else if (contactType == 'Volunteer' || contactType == 'Employee') {
    if (personnelStatus == null || personnelStatus == '') {
        personnelStatus = 'Active';
    }
}
if (contactType == 'MemberContact' && leaveDate != null && leaveDate < datetime\today()) {
    personnelStatus = 'Inactive';
} else if (contactType == 'MemberContact' && joinDate != null && joinDate > datetime\today()) {
    personnelStatus = 'Inactive';
} else if (contactType == 'MemberContact') {
    if (personnelStatus == null || personnelStatus == '') {
        personnelStatus = 'Active';
    }
}
